C.boost = { Viceroy = 3.0 }                 -- brand id -> multiplier on its 1993 share before the shares are normalised (Viceroy = the user's favourite)
C.matchTotalWeightRebalance = true          -- TrueCigs_Weights.lua: follow TotalWeightRebalance's cigarette weights when that mod is active
